class ReviewRepository:
    def __init__(self):
        self._reviews = []
        self._next_id = 1

    def add(self, book_id, text):
        review = {"id": self._next_id, "bookId": book_id, "text": text}
        self._reviews.append(review)
        self._next_id += 1
        return review

    def list_for_book(self, book_id):
        return [r for r in self._reviews if r["bookId"] == book_id]

